import {safeImageURL} from './media.js';
const cache=new Map(),queue=[],maximum=matchMedia('(pointer:coarse)').matches?8:16;let active=0;
export const lightNetwork=()=>navigator.connection?.saveData||/^(slow-2g|2g)$/.test(navigator.connection?.effectiveType??'');
function drain(){while(active<2&&queue.length){const entry=queue.shift();if(entry.cancelled)continue;active++;const img=new Image();img.decoding='async';img.referrerPolicy='no-referrer';img.fetchPriority=entry.urgent?'high':'low';entry.image=img;img.onload=async()=>{try{await img.decode()}catch{}entry.ready=true;entry.resolve(img);active--;trim();drain()};img.onerror=()=>{cache.delete(entry.src);entry.reject(Error('官方原图暂不可用'));active--;drain()};img.src=entry.src}}
function trim(){for(const [key,entry]of cache){if(cache.size<=maximum)break;if(entry.ready)cache.delete(key)}}
export function frameReady(src){return cache.get(src)?.ready===true}
export function loadFrame(value,urgent=true){const src=safeImageURL(value);if(!src)return Promise.reject(Error('原图地址无效'));let entry=cache.get(src);if(entry){cache.delete(src);cache.set(src,entry);if(urgent&&!entry.image){const i=queue.indexOf(entry);if(i>=0){queue.splice(i,1);queue.unshift(entry)}entry.urgent=true}return entry.promise}entry={src,urgent};entry.promise=new Promise((resolve,reject)=>Object.assign(entry,{resolve,reject}));cache.set(src,entry);urgent?queue.unshift(entry):queue.push(entry);while(queue.length>maximum*2){const old=queue.pop();old.cancelled=true;cache.delete(old.src);old.reject(Error('预加载已取消'))}drain();return entry.promise}
export function warmFrames(frames,index=0){if(lightNetwork()||frames.length<2||document.hidden)return;for(const offset of [1,-1,2])loadFrame(frames[(index+offset+frames.length)%frames.length],false).catch(()=>{})}
const versions=new WeakMap();
export function paintFrame(image,src){if(!src||image.dataset.requestedFrame===src)return;image.dataset.requestedFrame=src;const version=(versions.get(image)??0)+1;versions.set(image,version);loadFrame(src).then(()=>{if(versions.get(image)===version&&image.isConnected){image.src=src;image.dataset.decoded='true'}}).catch(()=>{if(versions.get(image)===version){delete image.dataset.requestedFrame;image.dispatchEvent(new Event('error'))}})}
